scripts.probe-hot-reclaim.mjs:
// Probe the interim Node hot-path mutex (events.lock): keep today's link/unlink
// fast path, but reclaim a dead holder's record only while holding a kernel
// "reclaim" lock (flock via helper exec, util-linux stand-in). Record = {pid,
// startTime, boot}. A1 schedule: R1 judged X dead and re-read it, then pauses
// right before unlink; R2 reclaims meanwhile. Run: node probe-hot-reclaim.mjs
import fs from 'node:fs';
import path from 'node:path';
import { spawn, spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { startTimeOf, currentBoot, judgeOwner, self } from './era-ledger.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ME = fileURLToPath(import.meta.url);
const sleepMs = (ms) => Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
const waitFile = (f, ms = 20000) => { const end = Date.now() + ms; while (!fs.existsSync(f)) { if (Date.now() > end) throw new Error(`timeout ${f}`); sleepMs(2); } };

function lockFd(fd) { return spawnSync('flock', ['-n', '3'], { stdio: ['ignore', 'ignore', 'ignore', fd] }).status === 0; }

/** One attempt: 'acquired' | 'held'. */
export function hotTryAcquire(lockPath, { reclaimLock = true, beforeUnlink } = {}) {
  const tmp = `${lockPath}.tmp-${process.pid}-${Math.random().toString(36).slice(2)}`;
  fs.writeFileSync(tmp, JSON.stringify({ ...self(), boot: currentBoot() }));
  try { fs.linkSync(tmp, lockPath); return 'acquired'; } catch (e) { if (e.code !== 'EEXIST') throw e; } finally { fs.unlinkSync(tmp); }
  let raw; try { raw = fs.readFileSync(lockPath, 'utf8'); } catch (e) { if (e.code === 'ENOENT') return 'retry'; throw e; }
  let rec = null; try { rec = JSON.parse(raw); } catch {}
  const dead = (r) => r && (r.boot !== currentBoot() || judgeOwner(r) === 'dead');
  if (!dead(rec)) return 'held'; // alive, unknown or unreadable: never reclaimed
  let rfd = null;
  if (reclaimLock) { rfd = fs.openSync(`${lockPath}.reclaim`, fs.constants.O_RDWR | fs.constants.O_CREAT); if (!lockFd(rfd)) { fs.closeSync(rfd); return 'held'; } }
  try {
    let cur; try { cur = fs.readFileSync(lockPath, 'utf8'); } catch (e) { if (e.code === 'ENOENT') return 'retry'; throw e; }
    if (cur !== raw) return 'retry';
    beforeUnlink?.();
    fs.unlinkSync(lockPath);
    return 'retry';
  } finally { if (rfd !== null) fs.closeSync(rfd); }
}
export function hotAcquire(lockPath, opts = {}) {
  for (let i = 0; i < 100000; i++) { const r = hotTryAcquire(lockPath, opts); if (r === 'acquired') return true; sleepMs(r === 'retry' ? 0 : 1); }
  return false;
}

const role = process.argv[2];
if (role === 'deadholder') { const [lp] = process.argv.slice(3); fs.writeFileSync(lp, JSON.stringify({ ...self(), boot: currentBoot() })); process.exit(0); }
if (role === 'R1') {
  const [lp, work, useLock] = process.argv.slice(3);
  const opts = { reclaimLock: useLock === '1', beforeUnlink: () => { if (!fs.existsSync(path.join(work, 'R1-go'))) { fs.writeFileSync(path.join(work, 'R1-paused'), ''); waitFile(path.join(work, 'R1-go')); } } };
  let r; do { r = hotTryAcquire(lp, opts); } while (r === 'retry');
  const others = r === 'acquired' ? fs.readdirSync(path.join(work, 'cs')).length : null;
  if (r === 'acquired') fs.writeFileSync(path.join(work, 'cs', 'R1'), '');
  fs.writeFileSync(path.join(work, 'R1.json'), JSON.stringify({ result: r, othersInsideOnEntry: others }));
  process.exit(0);
}
if (role === 'R2') {
  const [lp, work, useLock] = process.argv.slice(3);
  const ok = hotAcquire(lp, { reclaimLock: useLock === '1' });
  fs.writeFileSync(path.join(work, 'cs', 'R2'), '');
  fs.writeFileSync(path.join(work, 'R2-inside'), String(ok));
  waitFile(path.join(work, 'R2-leave'));
  fs.rmSync(path.join(work, 'cs', 'R2')); fs.unlinkSync(lp); process.exit(0);
}
if (role === 'stress') {
  const [lp, work, iters, useLock] = process.argv.slice(3);
  let v = 0, n = 0;
  for (let i = 0; i < Number(iters); i++) {
    hotAcquire(lp, { reclaimLock: useLock === '1', beforeUnlink: () => { if (Math.random() < 0.2) sleepMs(3); } }); n++;
    if (fs.readdirSync(path.join(work, 'cs')).filter((x) => x !== String(process.pid)).length) v++;
    fs.writeFileSync(path.join(work, 'cs', String(process.pid)), '');
    sleepMs(Math.floor(Math.random() * 2));
    fs.rmSync(path.join(work, 'cs', String(process.pid)), { force: true });
    fs.unlinkSync(lp);
  }
  fs.writeFileSync(path.join(work, `done-${process.pid}.json`), JSON.stringify({ n, v }));
  process.exit(0);
}

if (!role) {
  const report = [];
  const done = (cp) => new Promise((r) => cp.on('exit', r));
  for (const useLock of ['0', '1']) {
    const work = fs.mkdtempSync(path.join(HERE, `run-hot-a1-${useLock}-`)); fs.mkdirSync(path.join(work, 'cs'));
    const lp = path.join(work, 'events.lock');
    await done(spawn(process.execPath, [ME, 'deadholder', lp], { stdio: 'inherit' })); // X: holder died inside
    const R1 = spawn(process.execPath, [ME, 'R1', lp, work, useLock], { stdio: 'inherit' });
    waitFile(path.join(work, 'R1-paused'));
    const R2 = spawn(process.execPath, [ME, 'R2', lp, work, useLock], { stdio: 'inherit' });
    const t0 = Date.now(); while (!fs.existsSync(path.join(work, 'R2-inside')) && Date.now() - t0 < 1500) sleepMs(5);
    const r2InsideWhileR1Paused = fs.existsSync(path.join(work, 'R2-inside'));
    fs.writeFileSync(path.join(work, 'R1-go'), '');
    await done(R1);
    fs.writeFileSync(path.join(work, 'R2-leave'), '');
    if (!r2InsideWhileR1Paused) { /* R2 may enter only after R1 left */ }
    await new Promise((r) => setTimeout(r, 300));
    const r1 = JSON.parse(fs.readFileSync(path.join(work, 'R1.json'), 'utf8'));
    report.push({ case: `A1 schedule on events.lock, reclaim under kernel lock = ${useLock === '1'}`, r2EnteredWhileR1PausedBeforeUnlink: r2InsideWhileR1Paused, R1: r1, twoHolders: r1.result === 'acquired' && r1.othersInsideOnEntry > 0 });
    R2.kill('SIGKILL');
  }
  for (const useLock of ['0', '1']) {
    const work = fs.mkdtempSync(path.join(HERE, `run-hot-stress-${useLock}-`)); fs.mkdirSync(path.join(work, 'cs'));
    const lp = path.join(work, 'events.lock');
    const kids = [];
    let kills = 0;
    const startKid = (n) => { const k = spawn(process.execPath, [ME, 'stress', lp, work, String(n), useLock], { stdio: 'inherit' }); kids.push(k); return k; };
    for (let i = 0; i < 8; i++) startKid(150);
